custom_css:
:root {
  --studio-accent: #caa575; /* 强调颜色 */
  --studio-gap: 20px; /* 消息间距 */
  --studio-radius: 12px; /* 消息圆角 */
  --studio-font-size: 16px; /* 正文字号 */
  --studio-avatar-ratio: 1 / 1; /* 头像比例 */
}
#chat .mes { border-radius: var(--studio-radius); margin-bottom: var(--studio-gap); }
#chat .mes .name_text { color: var(--studio-accent); }
#chat .mes .mes_text { font-size: var(--studio-font-size); }
#chat .mes .avatar img { aspect-ratio: var(--studio-avatar-ratio); object-fit: cover; }
@media (max-width: 767px) {
  :root { --studio-gap: 12px; /* 手机消息间距 */ --studio-font-size: 14px; /* 手机字号 */ }
}
